?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?= $h($p['name']) ?> · S Hari Global</title><style>body{margin:0;font:17px/1.6 system-ui,sans-serif;background:#edf2fa;color:#172b55}main{max-width:820px;margin:36px auto;padding:28px;background:white;border-radius:24px;border-top:8px solid #f07a1e;box-shadow:0 20px 60px #10244c12}header{display:flex;flex-wrap:wrap;gap:24px;align-items:center}.portrait{width:150px;height:190px;object-fit:cover;border-radius:20px}h1{font-size:clamp(28px,5vw,44px);margin:8px 0}.pill{background:#e5f5ed;color:#18744e;padding:6px 12px;border-radius:20px}a.button{display:inline-block;margin:8px 8px 8px 0;padding:12px 20px;border-radius:12px;background:#0a2a8f;color:white;text-decoration:none}small{color:#66768b}@media(max-width:600px){main{margin:12px;padding:20px}}</style></head><body><main><header><?php if($p['photo']): ?><img class="portrait" src="?c=<?= rawurlencode($code) ?>&amp;photo=1" alt="<?= $h($p['name']) ?>"><?php endif; ?><div><small>S HARI GLOBAL PRIVATE LIMITED</small><h1><?= $h($p['name']) ?></h1><p><?= $h($p['roleEn']) ?> · <b><?= $h($p['memberCode']) ?></b></p><span class="pill"><?= $h($p['standing']) ?></span></div></header><h2>Travel with a familiar face</h2><p>Operating location: <?= $h($p['place']?:'Contact the office') ?></p><?php if(!empty($p['route'])): ?><p>Assigned route: <?= $h($p['route']) ?></p><?php endif; ?><div><?php if($wa): ?><a class="button" href="<?= $h($wa) ?>" rel="noopener">Chat on personal WhatsApp</a><?php endif; ?><a class="button" href="<?= $h(IdCard::verifyUrl($ref)) ?>">Check official card status</a><a class="button" href="<?= $h(appUrl()) ?>">Book a journey</a></div><p><small>The personal WhatsApp link opens a chat; official verification shows current company standing. Government IDs, bank details and application documents are private.</small></p><footer><small><?= $h($company['name']) ?> · <?= $h($company['phone']) ?></small></footer></main></body></html>
